#include "star4_switch.c"

void *epic_open(int primitive,int mode,int root,uint32_t count,uint32_t words,
                uint32_t capacity,uint32_t start,epic_emit_fn emit,void *user) {
    switch_ctx_t *ctx=calloc(1,sizeof(*ctx));
    if(!ctx)return NULL;
    ctx->capacity=capacity;ctx->input_count=count;ctx->base24=start;
    ctx->slots=calloc(capacity,sizeof(slot_state_t));
    if(!ctx->slots){free(ctx);return NULL;}
    ctx->cfg.primitive=(epic_primitive_t)primitive;ctx->cfg.mode=(epic_mode_t)mode;
    ctx->cfg.root_rank=root;ctx->cfg.payload_bytes=(int)words*4;
    ctx->cfg.count=(int)(count*words*(primitive==EPIC_PRIM_ALLGATHER?4:1));
    for(int r=0;r<4;r++) {
        epic_port_t *p=&ctx->cfg.ports[r];p->rank=r;
        p->host_mac[0]=2;p->host_mac[5]=(uint8_t)(r+1);
        p->switch_mac[0]=2;p->switch_mac[1]=1;p->switch_mac[5]=(uint8_t)(r+1);
        p->host_ip=htonl(0x0a000001u+(uint32_t)r);
        p->switch_ip=htonl(0x0a000065u+(uint32_t)r);
        p->host_qpn=0x100u+(uint32_t)r;p->switch_qpn=0x200u+(uint32_t)r;
        ctx->handles[r]=calloc(1,sizeof(pcap_t));
        if(!ctx->handles[r])abort();
        *ctx->handles[r]=(pcap_t){.user=user,.rank=r,.emit=emit};
    }
    return ctx;
}
void epic_close(void *context) {
    switch_ctx_t *ctx=context;if(!ctx)return;
    for(uint32_t i=0;i<ctx->capacity;i++)cleanup_slot(&ctx->slots[i]);
    for(int r=0;r<4;r++)free(ctx->handles[r]);
    free(ctx->slots);free(ctx);
}
int epic_ingress(void *context,int rank,const uint8_t *frame,size_t length) {
    return handle_packet(context,rank,frame,length);
}
int epic_flush(void *context) {return drain_ordered_results(context);}
int epic_retry(void *context,int rank) {(void)rank;return epic_flush(context);}
void epic_state(void *context,uint64_t *state) {
    switch_ctx_t *ctx=context;memset(state,0,32*sizeof(*state));state[0]=ctx->retired;
    for(uint32_t i=0;i<ctx->capacity;i++)state[1]+=ctx->slots[i].in_use;
    for(int r=0;r<4;r++) {state[2+r]=ctx->rx_next[r];state[6+r]=ctx->sent_next[r];state[10+r]=ctx->ack_next[r];state[14+r]=ctx->up_sent[r];}
    uint64_t values[]={ctx->rx_data,ctx->rx_ack,ctx->tx_data,ctx->tx_ack,ctx->accepted,
      ctx->duplicates,ctx->blocked,ctx->stale,ctx->invalid_wire,ctx->invalid_endpoint,
      ctx->ack_ignored,ctx->failed_sends,ctx->slot_overwrites};
    memcpy(state+18,values,sizeof(values));
}
static uint64_t fold_byte(uint64_t hash,uint8_t value){return (hash^value)*UINT64_C(1099511628211);}
static uint64_t fold_u64(uint64_t hash,uint64_t value){for(int j=0;j<8;j++){hash=fold_byte(hash,(uint8_t)value);value>>=8;}return hash;}
uint64_t epic_digest(void *context) {
    switch_ctx_t *ctx=context;uint64_t h=UINT64_C(14695981039346656037);
    for(uint32_t p=ctx->retired;p<ctx->input_count && p-ctx->retired<ctx->capacity;p++) {
        slot_state_t *slot=&ctx->slots[slot_idx(ctx,p)];
        if(!slot->in_use || slot->psn!=p)continue;
        h=fold_u64(h,p);h=fold_byte(h,slot->data_mask);h=fold_byte(h,slot->result_ready);
        if(ctx->cfg.primitive==EPIC_PRIM_ALLGATHER) {
            for(int r=0;r<4;r++) {
                h=fold_byte(h,slot->allgather_raw[r]!=NULL);
                if(slot->allgather_raw[r])for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->allgather_raw[r][j]);
            }
        } else if(ctx->cfg.primitive==EPIC_PRIM_BCAST) {
            for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->data.bcast_raw[j]);
        } else {
            for(int j=0;j<ctx->cfg.payload_bytes/4;j++) {
                uint32_t value;memcpy(&value,&slot->data.accum[j],4);
                for(int k=0;k<4;k++){h=fold_byte(h,(uint8_t)value);value>>=8;}
            }
        }
    }
    return h;
}
